package cn.zhuatech.spc.deep;import cn.zhuatech.spc.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/admin/spc-ops") public class DeepAdminController{private final DeepDomainService s;public DeepAdminController(DeepDomainService s){this.s=s;}@PostMapping("/characteristics/{id}/activate")ApiResponse<?> activate(@PathVariable Long id){return ApiResponse.ok(s.activate(id));}@PostMapping("/signals/{id}/verify")ApiResponse<?> verify(@PathVariable Long id,@Valid @RequestBody DeepDomainService.VerifyRequest r){return ApiResponse.ok(s.verify(id,r));}}
